@SpringBootTest
@Import(TestClockConfig.class)
class ReagentConcurrencyTest {

    @Autowired
    private ReagentService service;

    @Autowired
    private MutableClock clock;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanUp() {
